-- Customer Acquisition & Segmentation Analytics
-- SQLite; table `customers` is generated by: python src/analyze_customers.py
-- Customer names, original IDs and detailed addresses are intentionally excluded.
-- Acquisition costs have unspecified currency; NOT a verified marketing CAC metric.

-- 1. OVERALL PERFORMANCE
SELECT COUNT(*) AS customer_records,
       COUNT(DISTINCT record_id) AS unique_analysis_ids,
       ROUND(AVG(customer_acquisition_cost), 2) AS mean_cost_units,
       ROUND(SUM(customer_acquisition_cost), 2) AS recorded_cost_total_units,
       ROUND(AVG(customer_age), 1) AS mean_age_years
FROM customers;

-- 2. CUSTOMER SEGMENT MIX / COST
SELECT customer_segment,
       COUNT(*) AS customers,
       ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM customers), 2) AS customer_share_pct,
       ROUND(AVG(customer_acquisition_cost), 2) AS mean_cost_units,
       ROUND(SUM(customer_acquisition_cost), 2) AS recorded_cost_total_units
FROM customers
GROUP BY customer_segment
ORDER BY customers DESC;

-- 3. COUNTRY MIX / COST
SELECT customer_country,
       COUNT(*) AS customers,
       ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM customers), 2) AS customer_share_pct,
       ROUND(AVG(customer_acquisition_cost), 2) AS mean_cost_units
FROM customers
GROUP BY customer_country
ORDER BY customers DESC;

-- 4. REGION MIX (SOURCE-PROVIDED REGIONS, NOT VALIDATED REGIONAL GROUPINGS)
SELECT region, COUNT(*) AS customers,
       ROUND(AVG(customer_acquisition_cost), 2) AS mean_cost_units,
       ROUND(MIN(customer_acquisition_cost), 2) AS lowest_cost,
       ROUND(MAX(customer_acquisition_cost), 2) AS highest_cost
FROM customers
GROUP BY region
ORDER BY customers DESC;

-- 5. CUSTOMER AGE GROUPS
SELECT age_group, COUNT(*) AS customers,
       ROUND(AVG(customer_acquisition_cost), 2) AS mean_cost_units,
       ROUND(100.0 * COUNT(*) / (SELECT COUNT(*) FROM customers), 2) AS share_pct
FROM customers
GROUP BY age_group
ORDER BY CASE age_group
  WHEN '18–24' THEN 1 WHEN '25–34' THEN 2 WHEN '35–44' THEN 3
  WHEN '45–54' THEN 4 WHEN '55–64' THEN 5 ELSE 6 END;

-- 6. COUNTRY x SEGMENT
SELECT customer_country, customer_segment,
       COUNT(*) AS customers,
       ROUND(AVG(customer_acquisition_cost), 2) AS mean_cost_units
FROM customers
GROUP BY customer_country, customer_segment
ORDER BY customer_country, customers DESC;

-- 7. DISTRIBUTION INTO FOUR EQUAL-SIZED COST GROUPS
WITH bucketed AS (
  SELECT record_id, customer_acquisition_cost,
         NTILE(4) OVER (ORDER BY customer_acquisition_cost, record_id) AS cost_quartile
  FROM customers
)
SELECT cost_quartile, COUNT(*) AS customers,
       ROUND(MIN(customer_acquisition_cost), 2) AS min_cost_units,
       ROUND(MAX(customer_acquisition_cost), 2) AS max_cost_units,
       ROUND(AVG(customer_acquisition_cost), 2) AS mean_cost_units
FROM bucketed GROUP BY cost_quartile ORDER BY cost_quartile;

-- 8. DEMOGRAPHIC DISTRIBUTION (DO NOT INTERPRET AS CAUSATION)
SELECT gender, COUNT(*) AS customers,
       ROUND(AVG(customer_acquisition_cost), 2) AS mean_cost_units,
       ROUND(AVG(customer_age), 1) AS mean_age_years
FROM customers GROUP BY gender ORDER BY customers DESC;

-- 9. POSTAL CODE FORMAT AUDIT (AGGREGATE FLAGS, ORIGINAL CODES NOT PUBLISHED)
SELECT customer_country, postal_format_check, COUNT(*) AS records
FROM customers
GROUP BY customer_country, postal_format_check
ORDER BY customer_country, postal_format_check;

-- 10. QUALITY CHECKS
SELECT COUNT(*) AS records,
       SUM(CASE WHEN record_id IS NULL OR TRIM(record_id)='' THEN 1 ELSE 0 END) AS missing_analysis_ids,
       COUNT(*)-COUNT(DISTINCT record_id) AS duplicate_analysis_ids,
       SUM(CASE WHEN customer_age<18 OR customer_age>110 THEN 1 ELSE 0 END) AS ages_outside_expected_range,
       SUM(CASE WHEN customer_acquisition_cost<0 THEN 1 ELSE 0 END) AS negative_cost_rows
FROM customers;
